
import { StudioProApi } from "@mendix/extensions-api";
import { Knowledgebase } from "../../types/knowledgebase";

export const handleKnowledgebaseChangeValue = (studioPro: StudioProApi, field: keyof Knowledgebase, knowledgebase: Knowledgebase, setKnowledgebase: React.Dispatch<React.SetStateAction<Knowledgebase>>, documentId: string) => async (
    value: string
) => {
    console.log("knowledgebase change triggered for field ", field)
    const updatedKnowledgebase = { ...knowledgebase, [field]: value }
    setKnowledgebase(updatedKnowledgebase);
    await updateKnowledgebaseDocument(studioPro, updatedKnowledgebase, documentId);

};

const updateKnowledgebaseDocument = async (studioPro: StudioProApi, knowledgebase: Knowledgebase, documentId: string) => {
    console.log("Save logic triggered");
    try {
        await studioPro.app.model.customBlobDocuments.updateDocumentContent(documentId, knowledgebase);
    } catch (error) {
        studioPro.ui.notifications.show({
            title: "Failed to save document",
            message: (error as Error).message
        });
    }
};
